INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('f2c8c254-078f-48a4-a28e-06f7567a8848', '6509afa9-b5b5-4e70-9c17-21210f076c9f', '{3f723abc-425d-4b45-97e5-2c7d7d43c874}'::uuid[], 'BFD Crush', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', 'Meinl Byzance cymbals: (10 cymbals; range of stacked configs); 3 versions of kick (dampened, fully open, w/o resonant head); 3 snares across eight variations; 6 toms (2 floor, 4 rack)', 'perfect for all progressive and technical rock and metal genres. kick and toms recorded w/ mics intended for heavy music. Audix D6, Sennheiser E602, AKG D112, AEA R84. recorded a tiled surface to give some shimmer to your drum kit, and we brought back the infamous PZM microphones from the BFD Eldorado sessions - these microphones give you a huge room sound and can be the foundation of your mix. We also included a mono microphone positioned just in front of the drum kit, which can be crushed to hell and back to really fatten up your productions.', '{2e7b23f3-109f-4160-9499-c03f17807f8a,770560c4-2e7d-43ee-b6d1-f2b1e4d96ef9}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('6ab70518-b5da-45d2-b5a5-b6641672c607', '6509afa9-b5b5-4e70-9c17-21210f076c9f', NULL::uuid[], 'BFD Dan Foord Polyrhythmic Metal', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'Dan Foord', NULL, 'Modern tech model. Polyrhythms form the basis of this style and 3 over 4 most of all. Most comprehensive set of 3 over 4 polyrhythmic grooves and fills.', '{2e7b23f3-109f-4160-9499-c03f17807f8a}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('5d415f13-e4cc-4e92-978c-c2ed79f58a80', '6509afa9-b5b5-4e70-9c17-21210f076c9f', NULL::uuid[], 'BFD Dark Farm', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', '(3) Drum kits, including an all-copper kit by Q Drum Co. (11) Cymbals (3) Additional snare drums and (3) additional kick drums (11) Mix-ready presets (7) Groove Palettes and (287) individual Grooves', 'ideal for heavy metal, hard rock, and all forms of heavy or aggressive music Recorded at Middle Farm Studios, world-renowned for their punchy live room', '{2e7b23f3-109f-4160-9499-c03f17807f8a}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('53db8160-529d-483c-83d5-775dc2d8c0d6', '6509afa9-b5b5-4e70-9c17-21210f076c9f', '{edb8d5c4-985f-4b37-b3be-b785721d46ef,2bc45582-8ae6-4a34-bac2-c4ff7733626c}'::uuid[], 'BFD Heavy', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', '3 kicks (wood and felt beaters), 9 toms and a bonus reduced-detail Yamaha Jimmy Chamberlin steel-shell snare; (snare and toms have stick and mallets). Rim shots and Rim ckicks', 'designed for hard rock and metal styles', '{2e7b23f3-109f-4160-9499-c03f17807f8a,770560c4-2e7d-43ee-b6d1-f2b1e4d96ef9}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('2b45c55a-df26-46ac-b4ee-253fc58d1972', '6509afa9-b5b5-4e70-9c17-21210f076c9f', NULL::uuid[], 'BFD Heavy Rock Classics', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', NULL, 'authentic drum part recreations from all-time classics of the heavy rock genre', '{2e7b23f3-109f-4160-9499-c03f17807f8a}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('2b963f0f-ac59-4f8c-87be-36a0da1ebe1c', '6509afa9-b5b5-4e70-9c17-21210f076c9f', '{8c590a8c-6783-430f-8cf8-070858d8aef6}'::uuid[], 'BFD Horsepower', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', '6 configurable kits; sticks and brushes; Sabian hi-hats; Zildjian cymbals;', 'Americana-style drum sounds for a wide range of genres from blues and alt-country to garage rock and folk. Recorded w/ a perfect balance between vintage dirt and modern punch Warm ribbon-mic room ambience is accompanied by several ''character'' channels with saturated vintage tones, custom plate processing and even a unique trash can mic for lo-fi dirt. Snares were damped with paper and tea towels with the rest of the kit left untreated and tuned to the room for an open and vibrant sound that effortlessly slots into your mixes.', '{2e7b23f3-109f-4160-9499-c03f17807f8a,770560c4-2e7d-43ee-b6d1-f2b1e4d96ef9}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('901ff1b1-a34d-4b9a-8bd1-3e30473c0254', '6509afa9-b5b5-4e70-9c17-21210f076c9f', NULL::uuid[], 'BFD Jazz & Funk', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', 'Centred around 3 exquisitely recorded kits and a wide range of hyper-detailed extras, most of the instruments are provided in stick and brush versions with selected pieces also played with mallets, rods and even hands!', 'Recorded in a dry, intimate sounding room at Omega Studios, Maryland, USA, (jazz, funk, pop, soul, hip-hop, R&B, blues, country, fusion, folk, rock and far beyond.)', '{2e7b23f3-109f-4160-9499-c03f17807f8a}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('3bc83912-ff06-4c9b-aacb-cede544deeb9', '6509afa9-b5b5-4e70-9c17-21210f076c9f', '{55ded8ea-81eb-466e-94a9-0366708d430b}'::uuid[], 'BFD Jazz Maple', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', '2 kicks; 3 toms; bonus reduced-detail snare; Sabian cymbals', 'Maple warmth and sustain; particularly suited to jazz, fusion and funk, it''s great for any other musical styles that need expressive and great-sounding drums.', '{2e7b23f3-109f-4160-9499-c03f17807f8a,770560c4-2e7d-43ee-b6d1-f2b1e4d96ef9}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('3e4e717f-4f91-4780-9b4c-ffdb4d8f7159', '6509afa9-b5b5-4e70-9c17-21210f076c9f', '{aa70f363-63ce-49ec-b412-291723178448}'::uuid[], 'BFD Jazz Noir', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', 'rare, vintage Camco "Oaklawn"; sticks and brushes; Istanbul cymbals (inc. 24" ride); 1930s Round Badge Gretsch (snare)', 'jazz, funk and neo-soul, Camco drums are sought after by players and collectors alike for their clarity of tone and warm sustain; tuned medium high; Gretsch snare is low / fat alternative to Camco snare.
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('d09647e2-b841-45ee-a9da-c4a7cf5ce40a', '6509afa9-b5b5-4e70-9c17-21210f076c9f', NULL::uuid[], 'BFD JM Essentials Vol. 1', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', NULL, 'Produced by vastly experienced composer Jacques Mathias, contains varied, expressive patterns that cover genres such as rock, hard rock, alt-rock, heavy metal, trash metal and pop-punk.', '{2e7b23f3-109f-4160-9499-c03f17807f8a}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('3f726a88-38f6-4719-bb9c-f7a3de4ae5bf', '6509afa9-b5b5-4e70-9c17-21210f076c9f', NULL::uuid[], 'BFD JM Essentials Vol. 2', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', NULL, 'realistic set of reggae, funk, disco, swing, rockabilly, nu-metal and punk patterns', '{2e7b23f3-109f-4160-9499-c03f17807f8a}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('ca937da6-60f0-48ba-be7f-36080ad5950b', '6509afa9-b5b5-4e70-9c17-21210f076c9f', NULL::uuid[], 'BFD Metal Snares', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', '5 snares with different materials, shell thickness, depth, and diameter for wide array of sounds', 'Metal shells are desired for their brighter, louder sound with increased overtones.
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('0f7ed2c4-4f2c-435e-b1b1-a9b8ede2770f', '6509afa9-b5b5-4e70-9c17-21210f076c9f', NULL::uuid[], 'BFD Modern Drummer Snare Selects', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', '12 premium and boutique snares; all awarded ''Snare Drum of the Month'' status by Modern Drummer magazine and represent some of today''s most cutting-edge metal and wood shell designs.', 'Recorded with expressive detail levels, the instruments are all provided in snares-on versions along with selected alternate sounds with brushes, rods, hands and with snares off.', '{2e7b23f3-109f-4160-9499-c03f17807f8a}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('3d8566e5-0539-4a90-ae2c-f5d22f991480', '6509afa9-b5b5-4e70-9c17-21210f076c9f', '{91027a33-6294-4a6e-b391-9888594412d1,e395513a-67b1-43ca-8e5b-1cecfcddf0e0}'::uuid[], 'BFD Modern Retro', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion; produced and recorded by Chocolate Audio', '70 instruments; 1997 Sonor Designer and Tama Starclassic Kit; Ludwig, Sonor and Tama Snares; Zildjian, Ufip, Paiste, Turkish, Sabian hats/cymbals; hotrod, brush, kick beater (felt and plastic)', '2 kits that defined the sound of the 1990s and early 2000s. Kick recorded with 4 direct mics!The lush ambience of the recording space is captured with 2 sets of overhead and room mics. Designed to offer a variety of pop/rock-oriented sounds although the pack is perfect for all modern genres that demand detailed, focused and powerful-sounding drums.', '{2e7b23f3-109f-4160-9499-c03f17807f8a,770560c4-2e7d-43ee-b6d1-f2b1e4d96ef9}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
