INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('a9cd86a6-ef14-4db5-a191-d316dd8b97a1', '6509afa9-b5b5-4e70-9c17-21210f076c9f', '{dd076091-30d1-4cd4-a2f2-732ca422ea39}'::uuid[], 'BFD Oblivion', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', '3 different version of Mapex Orion; 2 snares (Mapex brass; Brady jarrah wood) cymbals (Bosphorous, Zildjian, Paiste)', 'Designed to provide ready-to-use heavy rock and metal drum sounds; inspired by genres like post-metal, sludge, prog-metal and alt-rock and are intended to have the punch to slice through the densest walls of guitars.', '{2e7b23f3-109f-4160-9499-c03f17807f8a,770560c4-2e7d-43ee-b6d1-f2b1e4d96ef9}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('65bfb370-bebd-476f-8ca0-c748989a69cb', '6509afa9-b5b5-4e70-9c17-21210f076c9f', NULL::uuid[], 'BFD Orchestral', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', 'variety of orchestral bass drums, snares and hand cymbals alongside chromatically tuned timpani and concert chimes which are sampled over 1.5 octaves and perfect for unusual melodic lines. suspended cymbals with huge decays due to the lack of a stand to dampen vibrations.', 'unique set of concert percussion; perfect for film / commercial composition as well as progressive music production and creative sound design.', '{2e7b23f3-109f-4160-9499-c03f17807f8a}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO instruments (instrument_id, brand_id, model_ids, instrument_name, version, instrument_type_ids, tool_type_ids, plugin_format_ids, description, instrument_notes, recording_notes, tag_ids, attributes) VALUES ('3269c3a0-0a9f-4861-bc85-a2d008998b2d', '6509afa9-b5b5-4e70-9c17-21210f076c9f', '{caf57397-c401-4f5b-85ee-5d0121c36bfc,c19a0709-6bf0-4cf3-9422-a61fb81c62a2}'::uuid[], 'BFD Sabian Digital Vault', NULL, '{708c24f3-8642-4640-b883-14842c8a95b7}'::uuid[], NULL::uuid[], NULL::uuid[], 'BFD3 Expansion', 'Diverse collection of cymbals and hihats from Sabian (AAX; HHX) unique stacked cymbal setups, esoteric percussion cymbals and 4 hyper-detailed hihats. Mallet and brush versions', 'All genres; Recordings performed by sampling guru John Emrich', '{2e7b23f3-109f-4160-9499-c03f17807f8a,770560c4-2e7d-43ee-b6d1-f2b1e4d96ef9}'::uuid[], NULL::jsonb) ON CONFLICT (instrument_id) DO UPDATE SET brand_id = EXCLUDED.brand_id, model_ids = EXCLUDED.model_ids, instrument_name = EXCLUDED.instrument_name, version = EXCLUDED.version, instrument_type_ids = EXCLUDED.instrument_type_ids, tool_type_ids = EXCLUDED.tool_type_ids, plugin_format_ids = EXCLUDED.plugin_format_ids, description = EXCLUDED.description, instrument_notes = EXCLUDED.instrument_notes, recording_notes = EXCLUDED.recording_notes, tag_ids = EXCLUDED.tag_ids, attributes = EXCLUDED.attributes, updated_at = NOW();
